using namespace std;
#define LL long long
#define MAXN 250005

int Mod;

int pow_mod(int base, int exp) {
    LL res=1, cur=base;
    while (exp>0) {
        if (exp&1) res=res*cur%Mod;
        cur=cur*cur%Mod;
        exp>>=1;
    }
    return (int)res;
}

int n, k;
int factorials[MAXN], inv_factorials[MAXN], inverses[MAXN], memo_table[19][MAXN];

int dfs(int used, int subset) {
    if (memo_table[used][subset]!=-1) return memo_table[used][subset];
    int answer=0;
    if (subset==0) {
        answer=factorials[n];
        for (int i=1;i<=used;++i)
            answer=1LL*answer*(k-i+1)%Mod;
        return memo_table[used][subset]=answer;
    }
    if (used>k) return 0;
    int lowest_bit = subset & (-subset);
    int remaining = subset - lowest_bit;
    for (int T=remaining;; T=(T-1)&remaining) {
        answer=(answer+1LL*inv_factorials[subset - T]*dfs(used+1,T)%Mod)%Mod;
        if (T==0) break;
    }
    return memo_table[used][subset]=answer;
}

int main() {
    scanf("%d%d%d",&n,&k,&Mod);
